        let vlr_rows=ordered(&database.table("las_vlr")?.rows,2,control)?;let vlr_ids:BTreeSet<_>=vlr_rows.iter().map(|row|row.rowid).collect();let mut octets=BTreeMap::<i64,Vec<&SqliteRow>>::new();let mut octet_ids=BTreeSet::new();
        for(index,row)in database.table("las_vlr_octet")?.rows.iter().enumerate(){if !octet_ids.insert(identity(row)?){return Err("LAS VLR octet identity is duplicated".into());}let owner=row.integer(1)?;if !vlr_ids.contains(&owner){return Err("LAS VLR octet has an unknown owner".into());}octets.entry(owner).or_default().push(row);if index%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,0)?;}}
        let mut vlrs=Vec::with_capacity(vlr_rows.len());for row in vlr_rows{document(row)?;let children=octets.get(&row.rowid).map(Vec::as_slice).unwrap_or(&[]);let data=ordered_refs(children.iter().copied(),children.len(),2,control)?.into_iter().map(|child|u8_at(child,3)).collect::<Result<Vec<_>,_>>()?;vlrs.push(LasVlr{user_id:row.text(3)?.into(),record_id:u16_at(row,4)?,description:row.text(5)?.into(),data});}
        let point_rows=ordered(&database.table("las_point")?.rows,2,control)?;let point_ids=point_rows.iter().map(|row|row.rowid).collect();let gps=components(&database.table("las_point_gps")?.rows,&point_ids,control)?;let rgb=components(&database.table("las_point_rgb")?.rows,&point_ids,control)?;let mut points=Vec::with_capacity(point_rows.len());
        for(index,row)in point_rows.iter().enumerate(){document(row)?;let value=FloatRow::new(row,POINT_FLOATS)?;points.push(LasPoint{x:value.real(3)?,y:value.real(4)?,z:value.real(5)?,intensity:u16_at(row,6)?,return_number:u8_at(row,7)?,number_of_returns:u8_at(row,8)?,scan_direction_flag:boolean(row,9)?,edge_of_flight_line:boolean(row,10)?,classification:u8_at(row,11)?,scan_angle_rank:i8::try_from(row.integer(12)?).map_err(|_|"LAS integer exceeds its native width")?,user_data:u8_at(row,13)?,point_source_id:u16_at(row,14)?,gps_time:gps.get(&row.rowid).map(|row|FloatRow::new(row,GPS_FLOATS)?.real(1)).transpose()?,rgb:rgb.get(&row.rowid).map(|row|Ok::<_,String>((u16_at(row,1)?,u16_at(row,2)?,u16_at(row,3)?))).transpose()?});if index%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,point_rows.len())?;}}
        control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,point_rows.len(),point_rows.len())?;Ok(Self{schema:document_row.text(1)?.into(),header,vlrs,points})
